            --border-color: #eee8d5;
        }

        [data-theme="dark"] {
            --bg-color: #073642;
            --text-color: #eee8d5;
            --card-bg: #002b36;
            --accent-color: #f6c17a;
            --border-color: #073642;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
