{"content":"<!DOCTYPE html>
<html lang="pt-br">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Jogo da Velha</title>
    <style>
        body {
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(3, 100px);
            grid-template-rows: repeat(3, 100px);
            gap: 5px;
            margin-bottom: 20px;
        }
        button {
            width: 100px;
            height: 100px;
            font-size: 2rem;
            cursor: pointer;
            border: 1px solid #333;
            background-color: white;
        }
        button:disabled {
            cursor: default;
        }
        #status {
            font-size: 1.5rem;
            margin-bottom: 20px;
            height: 2rem;
        }
        #reset {
            padding: 10px 20px;
            font-size: 1rem;
            cursor: pointer;
        }
    </style>
</head>
<body>

    <div id="status">Vez do X</div>

    <div class="grid">
        <button class="cell" data-cell="0"></button>
        <button class="cell" data-cell="1"></button>
        <button class="cell" data-cell="2"></button>
        <button class="cell" data-cell="3"></button>
        <button class="cell" data-cell="4"></button>
        <button class="cell" data-cell="5"></button>
        <button class="cell" data-cell="6"></button>
        <button class="cell" data-cell="7"></button>
        <button class="cell" data-cell="8"></button>
    </div>

    <button id="reset">Recomeçar</button>

    <script>
        const cells = document.querySelectorAll('.cell');
        const statusDisplay = document.getElementById('status');
        const resetBtn = document.getElementById('reset');
        let currentPlayer = 'X';
        let gameState = Array(9).fill(null);
        let gameActive = true;

        const winningConditions = [
            [0, 1, 2], [3, 4, 5], [6, 7, 8], // Horizontais
            [0, 3, 6], [1, 4, 7], [2, 5, 8], // Verticais
            [0, 4, 8], [2, 4, 6]             // Diagonais
        ];

        function handleCellClick(e) {
            const cellIndex = parseInt(e.target.getAttribute('data-cell'));

            if (gameState[cellIndex] !== null || !gameActive) {
                return;
            }

            gameState[cellIndex] = currentPlayer;
            e.target.innerText = currentPlayer;
            e.target.disabled = true;

            checkWinner();
        }

        function checkWinner() {
            let roundWon = false;
            for (let i = 0; i < winningConditions.length; i++) {
                const [a, b, c] = winningConditions[i];
                if (gameState[a] && gameState[a] === gameState[b] && gameState[a] === gameState[c]) {
                    roundWon = true;
                    break;
                }
            }

            if (roundWon) {
                statusDisplay.innerText = `${currentPlayer} venceu!`;
                gameActive = false;
                return;
            }

            if (!gameState.includes(null)) {
                statusDisplay.innerText = "Empate!";
                gameActive = false;
                return;
            }

            currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
            statusDisplay.innerText = `Vez do ${currentPlayer}`;
        }

        function resetGame() {
            currentPlayer = 'X';
            gameState = Array(9).fill(null);
            gameActive = true;
            statusDisplay.innerText = 'Vez do X';
            cells.forEach(cell => {
                cell.innerText = '';
                cell.disabled = false;
            });
        }

        cells.forEach(cell => cell.addEventListener('click', handleCellClick));
        resetBtn.addEventListener('click', resetGame);
    </script>
</body>
</html>
